package main

import (
	"context"
	"database/sql"
	"errors"
	"fmt"
	"net/http"
	"time"
)

// 1) 非导出类型当 key，外部包拿不到，从根源避免跨包撞车
type ctxKey int

const (
	traceIDKey ctxKey = iota
	tenantIDKey
)

func handler(w http.ResponseWriter, r *http.Request, db *sql.DB) {
	// 2) r.Context() 在客户端断开 TCP 时由 net/http 自动 cancel
	parent := r.Context()
	parent = context.WithValue(parent, traceIDKey, r.Header.Get("X-Trace-Id"))
	parent = context.WithValue(parent, tenantIDKey, r.Header.Get("X-Tenant-Id"))

	// 3) 给下游 DB 调用一个更短的子超时
	//    如果 parent deadline 还剩 200ms，这里 300ms 会被夹到 200ms
	ctx, cancel := context.WithTimeout(parent, 300*time.Millisecond)
	defer cancel() // 必须 defer：Stop timer 并从父 children map 摘除

	rows, err := db.QueryContext(ctx, "SELECT id FROM orders WHERE uid=$1", 42)
	if err != nil {
		// 4) errors.Is 区分超时和取消，监控指标分开打
		switch {
		case errors.Is(err, context.DeadlineExceeded):
			http.Error(w, "db timeout", http.StatusGatewayTimeout)
		case errors.Is(err, context.Canceled):
			// 客户端早断开，不用回写
			return
		default:
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
		return
	}
	defer rows.Close()

	// 5) 从 ctx 取 Value，用类型断言
	if tid, ok := ctx.Value(traceIDKey).(string); ok {
		w.Header().Set("X-Trace-Id", tid)
	}
	fmt.Fprintf(w, "ok")
}

// 6) 自己写的循环必须 select Done，裸 time.Sleep 无法响应取消
func poll(ctx context.Context, tick time.Duration) error {
	t := time.NewTicker(tick)
	defer t.Stop()
	for {
		select {
		case <-ctx.Done():
			return ctx.Err() // Canceled or DeadlineExceeded
		case <-t.C:
			// do work
		}
	}
}
